// Generated by `factory render`. Do not edit.
// The analysis CI jobs of the AI app factory (secret scan, dependency audit, ...), on any CI system:
//   node .factory/bin/analysis/ci.mjs --job <id> --base origin/<target branch>
// It needs only Node 20 and git: no factory install, no token. For each tool of the job it installs the pinned binary
// into FACTORY_CACHE_DIR (download, SHA-256 verified before anything runs), fetches its pinned rule source, runs its
// prepare step (an offline database), runs it on this commit and keeps the findings the pull request introduces
// (native: the tool scanned only the commit range; lines: on changed lines; merge-base: not reported at the merge-base).
// Findings already on the base are reported but do not fail the job. Exit 1 when the change introduces a finding the
// tool's block list names, or when a tool cannot run (a required check fails closed).
import { spawnSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { classify, identify, stripRulePrefix } from './baseline.mjs';
import { parserFor } from './parsers.mjs';
import { commandValidator, installBinary, pruneData, ruleSet } from './fetch.mjs';
import { expandSecretEnv, severityOf, triageOf } from './commercial.mjs';

// A tool's env with {placeholders} filled and `${NAME}` references read from the CI system's secret store (exposed as
// environment variables); a reference that is not set stops the tool (the job fails closed). Values are never printed.
function toolEnv(id, t, v) {
  const r = expandSecretEnv(Object.fromEntries(Object.entries(t.env ?? {}).map(([k, x]) => [k, expandOne(String(x), v)])));
  if (r.missing.length) throw new Error(`${id}: ${r.missing.join(', ')} not set (add ${r.missing.length > 1 ? 'them' : 'it'} to the CI system's secret store)`);
  return { ...process.env, ...r.env };
}

const here = path.dirname(fileURLToPath(import.meta.url));
const argv = process.argv.slice(2);
const opt = (name) => (argv.includes(name) ? argv[argv.indexOf(name) + 1] : null);
const jobId = opt('--job');
const base = opt('--base');
const root = process.cwd();
const sh = (cmd, args, o = {}) => spawnSync(cmd, args, { cwd: root, encoding: 'utf8', maxBuffer: 256 * 1024 * 1024, timeout: (o.timeoutSec ?? 600) * 1000, ...o });
const git = (args, cwd = root) => sh('git', args, { cwd });
const cacheDir = process.env.FACTORY_CACHE_DIR || path.join(os.tmpdir(), 'factory-cache');
const plat = `${process.platform}-${process.arch}`;

function fail(message) {
  console.error(`analysis: ${message}`);
  process.exit(2);
}

function matchGlob(file, glob) {
  let re = '';
  for (let i = 0; i < glob.length; i++) {
    const c = glob[i];
    if (c === '*' && glob[i + 1] === '*') {
      i++;
      if (glob[i + 1] === '/') {
        i++;
        re += '(?:.*/)?';
      } else re += '.*';
    } else if (c === '*') re += '[^/]*';
    else if (c === '?') re += '[^/]';
    else re += c.replace(/[.+^${}()|[\]\\]/g, '\\$&');
  }
  return new RegExp(`^${re}$`).test(file);
}

async function install(id, t) {
  if (!t.install) return null;
  const r = await installBinary(id, t.install, { cacheDir, plat });
  if (!r.ok) throw new Error(r.detail);
  return r.bin;
}

// The rule folders of a tool: the factory's own (rendered next to this script), a folder of the repository, or a pinned
// third-party set fetched here (only its included folders, at its commit, each file validated with the engine).
function ruleDirs(id, t, bin) {
  const dirs = [];
  for (const src of t.rules ?? []) {
    if (src.dirs) dirs.push(...src.dirs.map((d) => path.resolve(root, d)));
    else if (src.dir) dirs.push(path.resolve(root, src.dir));
    else if (src.repo) {
      const validate = t.validateRule ? commandValidator(expand(t.validateRule, { bin }), { cacheDir }) : null;
      const r = ruleSet(src, { cacheDir, validate });
      if (!r.ok) throw new Error(r.detail);
      console.log(`${id}: ${r.detail}`);
      for (const d of r.dropped ?? []) console.log(`${id}: rule file dropped: ${d.file} (${d.why})`);
      dirs.push(r.dir);
    }
  }
  return dirs;
}

const expandOne = (a, vars) =>
  a
    .replace(/\{files\}/g, (vars.files ?? []).join(' '))
    .replace(/\{rules\}/g, () => (vars.ruleDirs ?? []).map((d) => (vars.rulesArg ? `${vars.rulesArg} "${d}"` : `"${d}"`)).join(' '))
    .replace(/\{(out|base|mergeBase|range|root|bin|cache)\}/g, (_, k) => vars[k] ?? '')
    .replace(/\{([a-z][A-Za-z0-9]*)\}/g, (m, k) => (vars.extra && Object.hasOwn(vars.extra, k) ? vars.extra[k] : m));
const expand = (cmd, vars) => (Array.isArray(cmd) ? cmd.flatMap((a) => (a === '{files}' ? vars.files ?? [] : a === '{rules}' ? (vars.ruleDirs ?? []).flatMap((d) => (vars.rulesArg ? [vars.rulesArg, d] : [d])) : [expandOne(a, vars)])) : expandOne(cmd, vars));
const argvOf = (cmd) => (Array.isArray(cmd) ? [cmd[0], cmd.slice(1)] : process.platform === 'win32' ? ['cmd.exe', ['/d', '/s', '/c', cmd]] : ['sh', ['-c', cmd]]);

async function runTool(id, t, { cwd, vars }) {
  const out = path.join(os.tmpdir(), `factory-analysis-${id}-${process.pid}-${Math.random().toString(36).slice(2)}.out`);
  const v = { ...vars, out, root: cwd };
  const [cmd, args] = argvOf(expand(t.run, v));
  const env = toolEnv(id, t, v);
  const r = sh(cmd, args, { cwd, env, timeoutSec: t.timeoutSec ?? 600 });
  if (t.submitOnly) {
    if (r.status !== 0) throw new Error(`${id}: the upload failed (exit ${r.status}): ${String(r.stderr).trim().slice(-500)}`);
    return [];
  }
  try {
    if (r.error) throw new Error(`${id} could not run: ${r.error.message}`);
    const all = `${r.stdout ?? ''}${r.stderr ?? ''}`;
    if (t.missingPattern && new RegExp(t.missingPattern).test(all)) throw new Error(`${id} is not installed: ${all.trim().split('\n').pop()}`);
    if (t.errorPattern && new RegExp(t.errorPattern).test(all)) throw new Error(`${id}: ${all.match(new RegExp(`.*(${t.errorPattern}).*`))?.[0]}`);
    const text = t.output === 'stdout' || !t.output ? r.stdout : t.output === 'stderr' ? r.stderr : fs.existsSync(out) ? fs.readFileSync(out, 'utf8') : '';
    const parser = t.parse.startsWith('module:') ? await import(pathToFileURL(path.join(here, t.parse.slice(7))).href) : await parserFor(t.parse);
    let raw = parser.parse(text, { root: cwd });
    if (vars.ruleDirs?.length) raw = raw.map((f) => ({ ...f, rule: stripRulePrefix(f.rule, vars.ruleDirs, cwd) }));
    if (t.ruleFilter?.length) raw = raw.filter((f) => t.ruleFilter.some((x) => (x.endsWith('*') ? String(f.rule).startsWith(x.slice(0, -1)) : x === f.rule)));
    if (!raw.length && r.status !== 0 && !(t.okExit ?? [0, 1]).includes(r.status)) throw new Error(`${id} failed (exit ${r.status}): ${String(r.stderr).trim().slice(-500)}`);
    return identify(cwd, id, raw);
  } finally {
    fs.rmSync(out, { force: true });
  }
}

function changedMap(mergeBase) {
  const files = git(['diff', '--name-only', '--diff-filter=ACMR', mergeBase, 'HEAD']).stdout.split('\n').filter(Boolean);
  const map = new Map();
  for (const f of files) {
    if (git(['cat-file', '-e', `${mergeBase}:${f}`]).status !== 0) {
      map.set(f, null);
      continue;
    }
    const lines = new Set();
    for (const m of git(['diff', '-U0', '--no-ext-diff', mergeBase, 'HEAD', '--', f]).stdout.matchAll(/^@@ -\d+(?:,\d+)? \+(\d+)(?:,(\d+))? @@/gm)) for (let i = 0; i < (m[2] === undefined ? 1 : Number(m[2])); i++) lines.add(Number(m[1]) + i);
    map.set(f, lines);
  }
  return map;
}

async function main() {
  if (!jobId || !base) fail('usage: ci.mjs --job <id> --base <ref>');
  const data = JSON.parse(fs.readFileSync(path.join(here, 'jobs.json'), 'utf8'));
  const job = data.jobs.find((j) => j.id === jobId);
  if (!job) fail(`no job "${jobId}" (${data.jobs.map((j) => j.id).join(', ')})`);
  const mb = git(['merge-base', 'HEAD', base]);
  if (mb.status !== 0) fail(`no merge-base of HEAD and ${base} (fetch the base branch with full history)`);
  const mergeBase = mb.stdout.trim();
  const changed = changedMap(mergeBase);
  const tracked = git(['ls-files']).stdout.split('\n').filter(Boolean);
  let failed = false;
  const summary = [];
  for (const id of job.tools) {
    const t = data.tools[id];
    if (t.when?.length && !tracked.some((f) => t.when.some((g) => matchGlob(f, g)))) {
      console.log(`${id}: skipped (nothing matches ${t.when.join(', ')})`);
      continue;
    }
    const t0 = Date.now();
    try {
      if (t.needsRules && !(t.rules ?? []).length) {
        console.log(`${id}: skipped (no rule source configured)`);
        continue;
      }
      const bin = await install(id, t);
      const cache = path.join(cacheDir, 'data', id);
      fs.mkdirSync(cache, { recursive: true });
      const vars = { files: [...changed.keys()], base, mergeBase, range: `${mergeBase}..HEAD`, bin, ruleDirs: ruleDirs(id, t, bin), rulesArg: t.rulesArg, cache, extra: data.vars ?? {} };
      if (t.prepare) {
        const [c, a] = argvOf(expand(t.prepare, { ...vars, root }));
        const env = toolEnv(id, t, { ...vars, root });
        const p = sh(c, a, { timeoutSec: t.timeoutSec ?? 600, env });
        if (!(t.okExit ?? [0]).includes(p.status) || (t.errorPattern && new RegExp(t.errorPattern).test(`${p.stdout}${p.stderr}`))) throw new Error(`${id}: prepare failed (exit ${p.status}): ${String(p.stderr).trim().slice(-500)}`);
        for (const removed of pruneData(cache, t.data)) console.log(`${id}: removed excluded data ${path.basename(removed)} (licence)`);
      }
      const head = await runTool(id, t, { cwd: root, vars });
      if (t.submitOnly) {
        summary.push(`${id}: uploaded; the scanner's result for this commit is read from its server by the review gate`);
        continue;
      }
      let baseFindings = [];
      if (t.baseline === 'merge-base' && head.length) {
        const wt = fs.mkdtempSync(path.join(os.tmpdir(), 'factory-analysis-base-'));
        fs.rmSync(wt, { recursive: true, force: true });
        if (git(['-c', 'core.hooksPath=/dev/null', 'worktree', 'add', '--detach', '--quiet', wt, mergeBase]).status !== 0) throw new Error(`${id}: could not check out the merge-base`);
        try {
          baseFindings = await runTool(id, t, { cwd: wt, vars: { ...vars, files: [...changed.keys()].filter((f) => fs.existsSync(path.join(wt, f))), range: `${mergeBase}..${mergeBase}` } });
        } finally {
          git(['worktree', 'remove', '--force', wt]);
          fs.rmSync(wt, { recursive: true, force: true });
        }
      }
      const { introduced, preexisting } = classify(head, { scope: 'repo', baseline: t.baseline, changed, base: baseFindings });
      const blocking = (f) => !(t.commercial && triageOf(f)) && severityOf(t, f) === 'blocking';
      for (const f of t.commercial ? introduced.filter((x) => triageOf(x)) : []) console.log(`triaged  ${id} ${f.rule} ${f.file ?? '(no file)'}${f.line ? `:${f.line}` : ''}: ${triageOf(f)} in the scanner's own system (by a person; does not fail this job)`);
      const where = (f) => `${f.file ?? '(no file)'}${f.line ? `:${f.line}` : ''}`;
      const short = (m) => String(m ?? '').split('\n')[0].slice(0, 300);
      for (const f of introduced) console.log(`${blocking(f) ? 'BLOCKING' : 'finding '} ${id} ${f.rule} ${where(f)}: ${short(f.message)}`);
      for (const f of preexisting) console.log(`on base  ${id} ${f.rule} ${where(f)}: ${short(f.message)} (already on ${base}; does not fail this job)`);
      const nBlock = introduced.filter(blocking).length;
      if (nBlock) failed = true;
      summary.push(`${id}: ${introduced.length} introduced (${nBlock} blocking), ${preexisting.length} already on the base, ${Math.round((Date.now() - t0) / 1000)} s`);
    } catch (error) {
      failed = true;
      summary.push(`${id}: could not run: ${error.message}`);
    }
  }
  console.log(`\n${job.name}:\n${summary.map((s) => `- ${s}`).join('\n')}`);
  process.exitCode = failed ? 1 : 0;
}

await main();
